async def _run_graph_sync(state: EngineState, config: WorkflowConfig) -> EngineState:
    """Run graph synchronously."""
    logger = get_logger("engine.graph")

    # Ingestion
    state = await ingestion_node(state)
    if route_after_ingestion(state) == "error":
        raise RuntimeError(state.get("fatal_error", "Ingestion node failed"))

    # Drafter -> Critic Loop
    max_iterations = config.phases.get("critic", {}).get("config", {}).get("max_retries", 3) if isinstance(config.phases, dict) else 3

    for iteration in range(max_iterations):
        state = await drafter_node(state)
        if route_after_drafter(state) == "error":
            raise RuntimeError(state.get("fatal_error", "Drafter node failed"))

        state = await critic_node(state)
        next_phase = route_after_critic(state)

        if next_phase == "neo4j_builder":
            break
        elif next_phase == "drafter":
            logger.info(f"Retrying drafter (iteration {iteration + 1}/{max_iterations})")
        else:
            raise RuntimeError(state.get("fatal_error", "Critic node failed"))

    # Neo4j Builder
    state = await neo4j_builder_node(state)
    if route_after_neo4j_builder(state) == "error":
        raise RuntimeError(state.get("fatal_error", "Neo4j builder node failed"))

    # Synthesizer
    state = await synthesizer_node(state)
    if route_after_synthesizer(state) == "error":
        raise RuntimeError(state.get("fatal_error", "Synthesizer node failed"))

    return state

