import mimetypes

async def asr_transcribe(audio_path: Path) -> str:
    """Transcribe audio file using LiteLLM ASR endpoint."""
    logger.info(f"Transcribing audio: {audio_path}")

    try:
        async with httpx.AsyncClient() as client:
            with open(audio_path, 'rb') as f:
                # Determine mime type
                mime_type, _ = mimetypes.guess_type(str(audio_path))
                if not mime_type:
                    mime_type = "audio/mpeg" # Default fallback

                files = {'file': (audio_path.name, f, mime_type)}

                response = await client.post(
                    f"{LITELLM_BASE_URL}/audio/transcriptions", 
                    files=files, 
                    headers={"Authorization": f"Bearer {LITELLM_API_KEY}"},
                    timeout=60.0
                )

                if response.status_code != 200:
                    logger.warning(f"ASR failed with status {response.status_code}: {response.text}. Using placeholder.")
                    return f"[Audio Transcript for {audio_path.name}]"

                return response.json().get("text", "")

    except Exception as e:
        logger.error(f"ASR failed for {audio_path}: {e}")
        return f"[Audio Transcript for {audio_path.name}]" # Fallback to placeholder on network error

async def vlm_analyze(image_path: Path, prompt: str = "Describe this image in detail.") -> str:
    """Analyze image using LiteLLM VLM endpoint."""
    logger.info(f"Analyzing image: {image_path}")

    try:
        # 1. Encode image to base64
        with open(image_path, "rb") as image_file:
            base64_image = base64.b64encode(image_file.read()).decode('utf-8')

        # Determine mime type
        mime_type, _ = mimetypes.guess_type(str(image_path))
        if not mime_type:
            mime_type = "image/jpeg"

        # 2. Call LiteLLM VLM endpoint (Vision model)
        async with httpx.AsyncClient() as client:
            payload = {
                "model": "gpt-4o-mini", # Standard vision-capable model name for LiteLLM
                "messages": [
                    {
                        "role": "user",
                        "content": [
                            {"type": "text", "text": prompt},
                            {
                                "type": "image_url",
                                "image_url": {
                                    "url": f"data:{mime_type};base64,{base64_image}"
                                }
                            }
                        ]
                    }
                ],
                "max_tokens": 500
            }

            response = await client.post(
                f"{LITELLM_BASE_URL}/chat/completions",
                json=payload,
                headers={"Authorization": f"Bearer {LITELLM_API_KEY}"},
                timeout=30.0
            )

            if response.status_code != 200:
                logger.warning(f"VLM failed with status {response.status_code}: {response.text}. Using placeholder.")
                return f"[Image Description for {image_path.name}: A detailed analysis.]"

            return response.json()["choices"][0]["message"]["content"]

    except Exception as e:
        logger.error(f"VLM failed for {image_path}: {e}")
        return f"[Image Description for {image_path.name}: A detailed analysis.]"

